      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "As I continually upped my matchmaking skills in this game of \"siege warfare\", Victor kept finding more quibbling reasons to rebuff me.",
