    },
    [68] = {
      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "Personalities don't match. Tastes don't match. Sleep schedules don't match. Ideals don't match. Workplaces in different locations... Any excuse he could get, he would latch onto it.",
      next = {69}
    },
    [69] = {
      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "For my part, I gnashed my teeth on account of this troublesome Underworld God, but meanwhile, as I slowly got to know him, I also realized that he wasn't as unreasonable as the legends would have one believe.",
      next = {70}
    },
    [70] = {
      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "He would make a detailed examination of every departed life and give them the most suitable judgment, and then see them off out of the realm of the underworld.",
      next = {71}
    },
    [71] = {
      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "He also had a lot of hobbies that no one knew about. He drank wine, collected treasures, and he adored fresh fruit and bread hot out of the oven.",
      next = {72}
    },
    [72] = {
      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "He also knew a thing or two about architecture, and all of the palaces in the realm were of his design.",
      next = {73}
    },
    [73] = {
      beijing = 3191,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "One time, I saw him under a tree beside one of the various market fairs of the humans.",
      next = {74}
    },
    [74] = {
      beijing = 4221,
      dialog = 3,
      mask = "memory",
      music = "40_Produce_My_LOVE",
      renwu = "npc",
      sentence = "A tavern proprietor tried to sell him some fruit wine. Rather than just refuse, he actually bought some, and then went on silently watching the bustling marketplace.",
      next = {75}
    },
    [75] = {
      beijing = 4221,
      dhead = 111,
